{
 "api": 34,
 "comment": "Tier-3 acceptance spec (TESTING-STANDARD.md). Fallback coordinates are grounded in Blaze's real-device recording of v1.6.0 (540x1140 frames scaled x2): mode bar y~0.135, shutter center (0.451, 0.549), thumbnail (0.135, 0.549), gear (0.93, 0.065). tap_element grounds from the hierarchy first; fallbacks fire only if grounding fails. The after-back-* observes are the Back-walk evidence (Standard Part 3B): the analyzer asserts the package is still com.onioncore.camera and the viewfinder is back. Do NOT mark the Settings tap optional \u2014 if Settings cannot be opened, the run must fail loudly.",
 "density": 420,
 "height": 2280,
 "id": "camera-acceptance-v170",
 "image": "google_apis",
 "package": "com.onioncore.camera",
 "permissions": [
  "CAMERA",
  "RECORD_AUDIO",
  "POST_NOTIFICATIONS"
 ],
 "steps": [
  {
   "do": "record_start"
  },
  {
   "do": "screenshot",
   "label": "00-launch-early"
  },
  {
   "do": "wait",
   "seconds": 3
  },
  {
   "do": "observe",
   "label": "photo-viewfinder"
  },
  {
   "do": "screenshot",
   "label": "01-photo-viewfinder"
  },
  {
   "do": "tap_xy",
   "label": "shutter",
   "x": 0.451,
   "y": 0.572
  },
  {
   "do": "wait",
   "seconds": 2
  },
  {
   "do": "screenshot",
   "label": "02-after-capture"
  },
  {
   "do": "tap_xy",
   "label": "thumbnail",
   "x": 0.247,
   "y": 0.572
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "photo-view"
  },
  {
   "do": "back"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "after-back-photo"
  },
  {
   "do": "tap_element",
   "fallback_xy": [
    0.787,
    0.146
   ],
   "text": "MORE"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "more-grid"
  },
  {
   "do": "back"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "after-back-more"
  },
  {
   "do": "tap_element",
   "fallback_xy": [
    0.756,
    0.088
   ],
   "text": "Settings"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "settings"
  },
  {
   "do": "back"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "after-back-settings"
  },
  {
   "do": "tap_element",
   "fallback_xy": [
    0.421,
    0.146
   ],
   "text": "VIDEO"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "video-mode"
  },
  {
   "do": "back"
  },
  {
   "do": "wait",
   "seconds": 1
  },
  {
   "do": "observe",
   "label": "after-back-root"
  },
  {
   "do": "record_stop",
   "label": "flow"
  }
 ],
